using System;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace FoolLauncher {
 public sealed class ThemedDialog {
  public readonly Window Window;public readonly StackPanel Body,Buttons;
  public ThemedDialog(Window owner,string title,string subtitle){Window=new Window{Owner=owner,Title=title,Width=580,SizeToContent=SizeToContent.Height,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.CenterOwner,FontFamily=owner.FontFamily,FontSize=14};foreach(string key in new[]{"Panel","Hero","Button","Selection","Text","Muted","Accent","AccentText","Danger"}){var brush=((SolidColorBrush)owner.FindResource("Brush."+key)).Clone();var color=brush.Color;color.A=255;brush.Color=color;Window.Resources["Brush."+key]=brush;}Window.PreviewKeyDown+=(s,e)=>{if(e.Key==System.Windows.Input.Key.Escape){e.Handled=true;Window.Close();}};Window.Resources[typeof(Button)]=owner.FindResource(typeof(Button));Window.SetResourceReference(Control.ForegroundProperty,"Brush.Text");var border=new Border{CornerRadius=new CornerRadius(16),Padding=new Thickness(26),Margin=new Thickness(16),BorderThickness=new Thickness(1)};border.SetResourceReference(Border.BackgroundProperty,"Brush.Panel");border.SetResourceReference(Border.BorderBrushProperty,"Brush.Selection");border.Effect=new System.Windows.Media.Effects.DropShadowEffect{BlurRadius=22,ShadowDepth=4,Opacity=.28};var stack=new StackPanel();var heading=new Grid{Margin=new Thickness(0,0,0,12)};heading.ColumnDefinitions.Add(new ColumnDefinition());heading.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var name=new TextBlock{Text=title,FontSize=25,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center};heading.Children.Add(name);var close=Button("×",()=>Window.Close(),false);close.Margin=new Thickness(10,0,0,0);Grid.SetColumn(close,1);heading.Children.Add(close);heading.MouseLeftButtonDown+=(s,e)=>{if(e.ButtonState==System.Windows.Input.MouseButtonState.Pressed)Window.DragMove();};stack.Children.Add(heading);var hint=Text(subtitle);hint.Margin=new Thickness(0,0,0,20);hint.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");stack.Children.Add(hint);Body=new StackPanel();stack.Children.Add(Body);Buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,22,0,0)};stack.Children.Add(Buttons);border.Child=stack;Window.Content=border;}
  public static TextBlock Text(string value){return new TextBlock{Text=value,TextWrapping=TextWrapping.Wrap,LineHeight=23};}
  public Button Button(string title,Action action,bool primary){var b=new Button{Content=title,Padding=new Thickness(17,10,17,10),Margin=new Thickness(10,0,0,0)};if(primary){b.SetResourceReference(Control.BackgroundProperty,"Brush.Accent");b.SetResourceReference(Control.ForegroundProperty,"Brush.AccentText");}b.Click+=(s,e)=>action();return b;}
 }
 public sealed class JavaRequirementException:System.IO.IOException {public readonly int[] Majors;public JavaRequirementException(string message,params int[] majors):base(message){Majors=majors??new int[0];}}
 public static class JavaRequirementDialog {
  public static bool Show(Window owner,string message){bool navigate=false;var d=new ThemedDialog(owner,"需要调整 Java","为这个游戏版本选择兼容的 Java 后，再启动游戏。");var box=new Border{Padding=new Thickness(16),CornerRadius=new CornerRadius(9)};box.SetResourceReference(Border.BackgroundProperty,"Brush.Hero");box.Child=ThemedDialog.Text(message);d.Body.Children.Add(box);var hint=ThemedDialog.Text("可以在 Java 管理中下载所需版本、选择已有 Java，或恢复自动选择。");hint.Margin=new Thickness(0,14,0,0);hint.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");d.Body.Children.Add(hint);d.Buttons.Children.Add(d.Button("稍后",()=>d.Window.Close(),false));d.Buttons.Children.Add(d.Button("前往 Java 管理",()=>{navigate=true;d.Window.Close();},true));d.Window.ShowDialog();return navigate;}
 }
}
